<template>
  <!-- The Vue counterpart of Desk's "Connections" cards above a form: one
  card per connected form with this record's entry count. The card opens
  the list filtered to this record; "+" starts a new entry already linked. -->
  <section v-if="loading || connections.length" class="mb-6">
    <h2 class="mb-2 text-xs font-medium uppercase tracking-wide text-gray-500 dark:text-gray-400">Connections</h2>
    <div class="grid grid-cols-1 gap-2 min-[480px]:grid-cols-2 lg:grid-cols-3">
      <template v-if="loading && !connections.length">
        <Skeleton v-for="i in 3" :key="i" height="3rem" />
      </template>
      <template v-else>
      <div
        v-for="conn in connections"
        :key="conn.key"
        class="group relative flex items-center gap-3 rounded-lg px-3 py-2.5 ring-1 transition hover:shadow-sm focus-within:ring-2 focus-within:ring-gray-400"
        :class="conn.color"
      >
        <!-- Stretched ::after makes the whole card open the list; "+" sits
        above it (z-10) as its own separate action. -->
        <router-link
          :to="{ name: 'DoctypeList', params: { doctypeRoute: conn.item.route }, query: conn.query }"
          class="min-w-0 flex-1 truncate text-sm font-medium after:absolute after:inset-0 after:rounded-lg focus:outline-none"
          :title="conn.label"
        >
          {{ conn.label }}
        </router-link>
        <span
          v-if="conn.count"
          class="rounded-full bg-white px-2 py-0.5 text-xs font-medium tabular-nums text-gray-700 ring-1 ring-black/5 dark:bg-gray-900 dark:text-gray-300 dark:ring-white/10"
        >
          {{ conn.count }}
        </span>
        <router-link
          :to="{ name: 'DoctypeNew', params: { doctypeRoute: conn.item.route }, query: conn.query }"
          class="relative z-10 flex h-7 w-7 flex-shrink-0 items-center justify-center rounded-md text-gray-500 hover:bg-gray-900 hover:text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-gray-400 dark:hover:bg-gray-100 dark:hover:text-gray-900"
          :title="`New ${conn.label}`"
          :aria-label="`New ${conn.label}`"
        >
          <LucideIcon name="plus" class="h-4 w-4" />
        </router-link>
      </div>
      </template>
    </div>
  </section>
</template>

<script setup>
import { computed } from 'vue'
import { useCall } from 'frappe-ui'
import Skeleton from '@/components/Skeleton.vue'
import LucideIcon from '@/components/LucideIcon.vue'
import { findModuleByDoctype } from '@/data/modules'

const props = defineProps({
  doctype: { type: String, required: true },
  name: { type: String, required: true },
})

// Fetched per mount - the form remounts per record (remountOnParamChange),
// and counts should be fresh each time a record is opened, so no cacheKey.
const connectionsResource = useCall({
  url: '/api/v2/method/chw.api.get_doc_connections',
  method: 'GET',
  params: { doctype: props.doctype, name: props.name },
})

const loading = computed(() => connectionsResource.loading)

// Light tints, cycled per card so neighbouring connections are easy to tell
// apart. Full class strings so Tailwind's content scan picks them up.
const CARD_COLORS = [
  'bg-blue-50 ring-blue-100 text-blue-900 dark:bg-blue-900/30 dark:ring-blue-900 dark:text-blue-100',
  'bg-green-50 ring-green-100 text-green-900 dark:bg-green-900/30 dark:ring-green-900 dark:text-green-100',
  'bg-purple-50 ring-purple-100 text-purple-900 dark:bg-purple-900/30 dark:ring-purple-900 dark:text-purple-100',
  'bg-orange-50 ring-orange-100 text-orange-900 dark:bg-orange-900/30 dark:ring-orange-900 dark:text-orange-100',
  'bg-teal-50 ring-teal-100 text-teal-900 dark:bg-teal-900/30 dark:ring-teal-900 dark:text-teal-100',
  'bg-pink-50 ring-pink-100 text-pink-900 dark:bg-pink-900/30 dark:ring-pink-900 dark:text-pink-100',
]

// Only connected forms this app has a page for - anything else couldn't be
// opened from here anyway.
const connections = computed(() =>
  (connectionsResource.data || [])
    .map((conn) => {
      const item = findModuleByDoctype(conn.doctype)
      if (!item) return null
      return {
        key: `${item.route}:${conn.fieldname}`,
        item,
        label: item.label || item.doctype_name,
        count: conn.count,
        query: { [conn.fieldname]: props.name },
      }
    })
    .filter(Boolean)
    // Coloured after filtering so the shown cards cycle without gaps.
    .map((conn, index) => ({ ...conn, color: CARD_COLORS[index % CARD_COLORS.length] })),
)
</script>
